package org.eclipse.jdt.internal.ui.packageview;

import org.eclipse.core.runtime.IAdaptable;
import org.eclipse.jdt.ui.JavaElementImageDescriptor;

// This class demonstrates usage of the constant before it became public API.
// Assumes existence of IAdaptable and JavaElementImageDescriptor types. 
// In this context, BUILDPATH_ERROR refers to the one declared within this class.
public class PackageExplorerProblemsDecorator {
    public final static int BUILDPATH_ERROR = 0x2000; // Internal declaration

    public int computeAdornmentFlags(IAdaptable element) {
        int flags = 0; // Simplified for example context
        if ((flags & PackageExplorerProblemsDecorator.BUILDPATH_ERROR) != 0) {
            return PackageExplorerProblemsDecorator.BUILDPATH_ERROR;
        }
        if ((flags & JavaElementImageDescriptor.ERROR) != 0) {
            return JavaElementImageDescriptor.ERROR;
        }
        return flags;
    }
}

